CREATE TEMPORARY VIEW base_table_${grass_region_without_quote} AS
select local_hour
     ,cspu_id
     ,model_id
     ,item_id
     ,a.shop_id
     ,coalesce(b.type,'non-scs') as shop_scs_type
from srdi_mart.dim_sr_data_warehouse_pb_all_cspu_link_analysis_hf a
left join (
    select type
         ,shop_id
    from regds_listing.dim_scs_shop_list_df
    where grass_region = ${grass_region}
      and type in ('scs-local','scs-cb')
)b
on a.shop_id = b.shop_id
where grass_region = ${grass_region}
  and local_date = ${local_date}
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW biz_type_${grass_region_without_quote} AS
SELECT local_hour
    ,model_id
    ,cspu_id
    ,shop_id
    ,business_type
from srdi_mart.dim_sr_data_warehouse_pb_one_variation_model_analysis_hf
where grass_region = ${grass_region}
  and local_date = ${local_date}
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW cspu_type_${grass_region_without_quote} AS
select local_hour
     ,cspu_id
     ,collect_list(model_type) cspu_type
from(
        select a.local_hour
             ,a.cspu_id
             ,case when business_type = 1 then 1.1
                   when business_type = 3 then 3.1
                   when business_type = 2 and b.type = 'scs-cb' then 2.1
                   when business_type = 2 and b.type = 'scs-local' then 2.2
                   when business_type = 4 and b.type = 'scs-cb' then 4.1
                   when business_type = 4 and b.type = 'scs-local' then 4.2
            end as model_type
        from biz_type_${grass_region_without_quote} a
        left join (
            select type
                 ,shop_id
            from regds_listing.dim_scs_shop_list_df
            where grass_region = ${grass_region}
              and type in ('scs-local','scs-cb')
        ) b
        on a.shop_id = b.shop_id
        group by 1,2,3
    )a
group by 1,2
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW basic_aggr_model_${grass_region_without_quote} AS
select local_hour
     ,item_id
     ,model_id
     ,sum(imp_cnt) imp_cnt
     ,sum(case when is_ads='false' then imp_cnt end) as org_imp_cnt
     ,sum(order_cnt) as model_order_cnt
     ,sum(case when is_ads='false' then order_cnt  end) as model_org_order_cnt
     ,sum(gmv) as model_gmv
     ,sum(case when is_ads='false' then gmv end) as model_org_gmv
     ,sum(gmv_local) as model_gmv_local
     ,sum(case when is_ads='false' then gmv_local end) as model_org_gmv_local
from srdi_mart.dws_sr_data_warehouse_tc_pb_basic_aggr_1d
where grass_region = ${grass_region}
  and local_date = ${local_date}
  and mapping_general = 'S&R__ALL__'
group by 1,2,3
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW basic_aggr_item_${grass_region_without_quote} AS
select local_hour
     ,item_id
     ,sum(org_imp_cnt) as item_org_imp_cnt
     ,sum(imp_cnt) as item_imp_cnt
from basic_aggr_model_${grass_region_without_quote}
group by 1,2
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW cspul1d_table_${grass_region_without_quote} AS
select cspu_id
     ,sum(order_cnt) as cspu_l1d_order_cnt
from srdi_mart.dws_sr_data_warehouse_tc_pb_cspu_level_1d
where grass_region = ${grass_region}
  and local_date = date_sub(${local_date},1)
group by 1
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW vmodel_${grass_region_without_quote} AS
SELECT local_hour
    ,model_id
FROM srdi_mart.dim_sr_data_warehouse_vsku_model_mapping_hf
where grass_region in (${grass_region})
  and local_date = ${local_date}
group by 1,2
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW final_table_${grass_region_without_quote} AS
select a.cspu_id
     ,a.model_id
     ,a.item_id
     ,a.shop_id
     ,a.shop_scs_type
     ,e.business_type
     ,f.cspu_type
     ,coalesce(item_org_imp_cnt,0) item_org_imp_cnt
     ,coalesce(item_imp_cnt,0) item_imp_cnt
     ,coalesce(model_org_order_cnt,0) model_org_order_cnt
     ,coalesce(model_order_cnt,0) model_order_cnt
     ,coalesce(model_org_gmv,0) model_org_gmv
     ,coalesce(model_gmv,0) model_gmv
     ,coalesce(model_org_gmv_local,0) model_org_gmv_local
     ,coalesce(model_gmv_local,0) model_gmv_local
     ,coalesce(d.cspu_l1d_order_cnt,0) cspu_l1d_order_cnt
     ,if(g.model_id is not null, 1, 0) is_buybox
     ,a.local_hour
from base_table_${grass_region_without_quote} a
left join basic_aggr_model_${grass_region_without_quote} b
on a.local_hour = b.local_hour
and a.model_id = b.model_id
left join basic_aggr_item_${grass_region_without_quote} c
on a.local_hour = c.local_hour
and a.item_id = c.item_id
left join cspul1d_table_${grass_region_without_quote} d
on a.cspu_id = d.cspu_id
left join biz_type_${grass_region_without_quote} e
on a.local_hour = e.local_hour
and a.model_id = e.model_id
and a.cspu_id = e.cspu_id
left join cspu_type_${grass_region_without_quote} f
on a.local_hour = f.local_hour
and a.cspu_id = f.cspu_id
left join vmodel_${grass_region_without_quote} g
on a.local_hour = g.local_hour
and a.model_id = g.model_id
;

